import { NextResponse } from "next/server";
import { authenticateTeam, ensureRoomsTable, tokenDigest, validToken } from "@/lib/team-auth";
import { getCoilsideCloudBindings } from "@/lib/cloud-server";

export const dynamic = "force-dynamic";

// Creating a private room is the only anonymous write. The two cryptographically
// random secrets are generated by the owner's browser. No email enrollment.
export async function POST(request: Request) {
  const db = getCoilsideCloudBindings().COILSIDE_DB;
  if (!db) return NextResponse.json({ error: "Cloud storage is not connected yet. Your existing records are untouched." }, { status: 503 });
  const raw = await request.text();
  if (raw.length > 512) return NextResponse.json({ error: "Invalid pairing request." }, { status: 413 });
  let data: { ownerToken?: unknown; seanToken?: unknown };
  try { data = JSON.parse(raw) as { ownerToken?: unknown; seanToken?: unknown }; }
  catch { return NextResponse.json({ error: "Invalid pairing request." }, { status: 400 }); }
  if (!validToken(data.ownerToken) || !validToken(data.seanToken) || data.ownerToken === data.seanToken)
    return NextResponse.json({ error: "Invalid pairing codes." }, { status: 400 });
  try {
    await ensureRoomsTable(db);
    const room = crypto.randomUUID();
    const [ownerHash, seanHash] = await Promise.all([tokenDigest(data.ownerToken),tokenDigest(data.seanToken)]);
    await db.prepare("INSERT INTO coilside_rooms(id, owner_hash, sean_hash, created_at) VALUES(?, ?, ?, ?)")
      .bind(room, ownerHash, seanHash, Date.now()).run();
    return NextResponse.json({ room }, { status: 201, headers: { "cache-control": "no-store" } });
  } catch { return NextResponse.json({ error: "Could not create private team room." }, { status: 503 }); }
}

export async function GET(request: Request) {
  const actor = await authenticateTeam(request);
  if (!actor.ok) return NextResponse.json({ error: actor.error }, { status: actor.status });
  return NextResponse.json({ role: actor.role, room: actor.room }, { headers: { "cache-control": "no-store" } });
}
